def merge_intervals(xs):
    if not xs:
        return []
    sorted_xs = sorted(xs, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_xs[0])]
    for start, end in sorted_xs[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return [(s, e) for s, e in merged]
