class Cache:
    def __init__(self):
        self._data = {}

    def put(self, key, value, now, ttl):
        if ttl <= 0:
            self._data[key] = (now, value, now + ttl)
        else:
            self._data[key] = (now, value, now + ttl)

    def get(self, key, now):
        if key not in self._data:
            return None
        insertion_time, value, expiry_time = self._data[key]
        if now >= expiry_time:
            del self._data[key]
            return None
        return value
