def merge_patch(target, patch):
    if patch is None:
        return None
    if isinstance(patch, dict):
        if not isinstance(target, dict):
            target = {}
        result = dict(target)
        for key, value in patch.items():
            if value is None:
                result.pop(key, None)
            else:
                result[key] = merge_patch(target.get(key), value)
        return result
    return patch
